if (id === 'exams') return exams();
if (id === 'where') return one(id, 'Where would you like to study?', '', [['near', 'Close to home', 'In or near my home state'], ['india', 'Anywhere in India'], ['abroad', 'Abroad, if possible']], A.where, v => { A.where = v; });
