try { sessionStorage.setItem('mum-check', JSON.stringify({ cls: { '11': 'Class 11', '12': 'Class 12' }[A.cls] || '', stream: { pcm: 'Science (PCM)', pcmb: 'Science (PCM)', pcb: 'Science (PCB)', comm: 'Commerce', com: 'Commerce', hum: 'Humanities' }[A.stream] || '' })); } catch (x) {}
