const label = s => s / best > .85 ? 'Strong match' : s / best > .6 ? 'Good match' : 'Worth exploring';
const chip = e => ON_CAL.includes(e) ? `<a href="${link('cal')}">${e}</a>` : `<span>${e}</span>`;
const html = top.map((o, n) => {
const c = CL[o.k], pick = A.deep[o.k] != null && c.dq ? c.dq.o[A.deep[o.k]][1] : {};
const loved = T.filter(([, w], i) => A.cards[i] === 2 && w[o.k] >= .5).map(([t]) => t).slice(0, 2);
let list = c.co.map((x, i) => ({ x, i, fits: early || x.st.includes(st) }));
list.sort((a, b) => (b.i === pick.co) - (a.i === pick.co) || b.fits - a.fits);
const notes = [];
if (pick.f) notes.push(pick.f);
if (pick.pm && st && !['pcm', 'pcmb'].includes(st)) notes.push('With your stream, the Army wing is the route open to you.');
if (!early && !list.some(l => l.fits)) notes.push(`Most courses here need ${c.s}. A counsellor can show you the routes still open with your subjects.`);
if (A.exams && !A.exams.includes('none') && !c.co.some(ok)) notes.push('These courses need an entrance exam you did not pick. Worth a second look if this area excites you.');
if (A.exams && A.exams.includes('none') && !c.co.some(x => x.ex.some(e => OPEN.includes(e)))) notes.push('This area needs a national entrance exam. A counsellor can tell you when to start preparing.');
const courses = list.map(({ x, i, fits }) => `<li class="${fits ? '' : 'nofit'}${i === pick.co ? ' pick' : ''}"><div><strong>${x.n}</strong>${i === pick.co ? '<em>Your pick</em>' : ''}${!fits ? '<em class="warn">Needs a different stream</em>' : ''}</div><span>${x.why} ${x.y}.</span><div class="cc-exams">${x.ex.map(chip).join('')}</div>${x.g ? `<a class="cc-guide" href="${link(x.g)}">Read our guide</a>` : ''}</li>`).join('');
return `<article class="cc-area"><div class="cc-area-head"><span class="cc-rank">${n + 1}</span><div><h3>${c.n}</h3><p>${c.c}</p></div><span class="cc-tag t${n}">${label(o.s)}</span></div>
<div class="cc-meter"><span style="--w:${Math.max(20, Math.round(o.s / best * 100))}%"></span></div>
${loved.length ? `<div class="cc-why"><b>Why this fits you</b><ul>${loved.map(t => `<li>You said you would love to ${t.charAt(0).toLowerCase() + t.slice(1)}.</li>`).join('')}</ul></div>` : ''}
${early ? `<p class="cc-stream">Stream for this path: <strong>${c.s}</strong></p>` : ''}
${notes.map(t => `<p class="cc-note">${t}</p>`).join('')}
<ul class="cc-courses">${courses}</ul></article>`;
}).join('');
const extra = r.slice(3).find(o => o.raw > 0);
const tips = [];
if (early) {
const tk = top[0].k, want = CL[tk].s;
if (!A.stream || A.stream === 'und') tips.push(`Your top match points to <strong>${want}</strong> in Class 11.`);
else if (CL[tk].co.some(c => c.st.includes(A.stream))) tips.push(`Your top match fits <strong>${SN(A.stream)}</strong>, the stream you are thinking of.`);
else tips.push(`Your top match usually needs <strong>${want}</strong>. You were thinking of ${SN(A.stream)} — worth talking through before you decide.`);
tips.push(`Read <a href="${link('stream')}">how to choose your stream after Class 10</a>.`);
}
if (A.cls === '12') tips.push(`Some entrance exam registrations may already be open or closing soon. Check every date on our <a href="${link('cal')}">exam calendar</a>.`);
