if (A.years === '3' && top.some(o => CL[o.k].co.every(c => /^[45]/.test(c.y)))) tips.push('Some paths above take four years or more. A counsellor can show you shorter routes into the same field.');
if (A.where === 'near') tips.push(`A counsellor can shortlist good universities in and around ${A.city ? esc(A.city) : 'your home state'}. You can also browse our <a href="${link('net')}">partner universities</a>.`);
