stage.querySelector('.cc-restart').addEventListener('click', () => { const keep = { name: A.name, phone: A.phone, school: A.school, city: A.city }; for (const k in A) delete A[k]; Object.assign(A, keep, { cards: [], deep: {} }); pos = 0; ci = 0; root.querySelector('.cc-top').hidden = false; root.querySelector('.cc-nav').hidden = false; root.classList.remove('is-result'); render(); root.scrollIntoView({ behavior: 'smooth' }); });
requestAnimationFrame(() => stage.querySelectorAll('.cc-meter span').forEach(s => s.classList.add('go')));
root.scrollIntoView({ behavior: 'smooth', block: 'start' });
